
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_apbe0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_apbe0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.305947444370379e+00, -3.243889561031770e+00, -3.156992402077250e+00, -3.036747046220797e+00, -2.873171174054256e+00, -2.656046830267681e+00, -2.377813543921389e+00, -2.038678758657158e+00, -1.652783260778944e+00, -1.247254799716356e+00, -8.422452079843483e-01, -5.714327092717595e-01, -4.976014602458350e-01, -4.090034461323557e-01, -2.964426177665667e-01, -1.893528804851178e-01, -1.017184640458470e-01, -3.724432602622200e-02, -8.110060190424326e-03, -9.121532350500186e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


